#[cfg(test)]
mod tests {
    use super::*;

    fn range_text(entry: &UnicodeRange) -> String {
        match entry {
            R(a, b) => format!("{a}-{b}"),
            S(a) => format!("{a}"),
        }
    }

    fn table_text(table: UnicodeRangeTable) -> String {
        table.iter().map(range_text).collect::<Vec<_>>().join(",")
    }

    fn surrogate_table_text(table: UnicodeSurrogateRangeTable) -> String {
        table
            .iter()
            .map(|(high, ranges)| format!("{high}:[{}]", table_text(ranges)))
            .collect::<Vec<_>>()
            .join(",")
    }

    /// Rebuilds the canonical text of `tools/unicode_tables.mjs canonical` from the
    /// compiled tables and compares it with the output for the pinned unicode.ts.
    #[test]
    #[cfg_attr(miri, ignore = "runs node, and Miri cannot start a process")]
    fn tables_match_typescript() {
        let mut rust = String::new();
        rust.push_str(&format!("unicodeLu={}\n", table_text(UNICODE_LU)));
        rust.push_str(&format!(
            "unicodeLuSurrogate={}\n",
            surrogate_table_text(UNICODE_LU_SURROGATE)
        ));
        rust.push_str(&format!("unicodeLl={}\n", table_text(UNICODE_LL)));
        rust.push_str(&format!(
            "unicodeLlSurrogate={}\n",
            surrogate_table_text(UNICODE_LL_SURROGATE)
        ));
        rust.push_str(&format!("unicodeLt={}\n", table_text(UNICODE_LT)));
        rust.push_str(&format!("unicodeLo={}\n", table_text(UNICODE_LO)));
        rust.push_str(&format!(
            "unicodeLoSurrogate={}\n",
            surrogate_table_text(UNICODE_LO_SURROGATE)
        ));
        rust.push_str(&format!("unicodeLm={}\n", table_text(UNICODE_LM)));
        rust.push_str(&format!(
            "unicodeLmSurrogate={}\n",
            surrogate_table_text(UNICODE_LM_SURROGATE)
        ));
        rust.push_str(&format!("unicodeNl={}\n", table_text(UNICODE_NL)));
        rust.push_str(&format!(
            "unicodeNlSurrogate={}\n",
            surrogate_table_text(UNICODE_NL_SURROGATE)
        ));
        rust.push_str(&format!("unicodeMn={}\n", table_text(UNICODE_MN)));
        rust.push_str(&format!(
            "unicodeMnSurrogate={}\n",
            surrogate_table_text(UNICODE_MN_SURROGATE)
        ));
        rust.push_str(&format!("unicodeMc={}\n", table_text(UNICODE_MC)));
        rust.push_str(&format!(
            "unicodeMcSurrogate={}\n",
            surrogate_table_text(UNICODE_MC_SURROGATE)
        ));
        rust.push_str(&format!("unicodeNd={}\n", table_text(UNICODE_ND)));
        rust.push_str(&format!(
            "unicodeNdSurrogate={}\n",
            surrogate_table_text(UNICODE_ND_SURROGATE)
        ));
        rust.push_str(&format!("unicodePc={}\n", table_text(UNICODE_PC)));

        let tool = concat!(
            env!("CARGO_MANIFEST_DIR"),
            "/../../tools/unicode_tables.mjs"
        );
        let output = std::process::Command::new("node")
            .arg(tool)
            .arg("canonical")
            .output()
            .expect("run node tools/unicode_tables.mjs canonical");
        assert!(
            output.status.success(),
            "{}",
            String::from_utf8_lossy(&output.stderr)
        );
        let typescript = String::from_utf8(output.stdout).unwrap();
        assert!(
            rust == typescript,
            "unicode.rs differs from unicode.ts; rerun tools/unicode_tables.mjs generate"
        );
    }
}
